/** Hide SVG name glyphs while SplitText overlay runs (survives React innerHTML resets). */
const hideHeroNameSvgGlyphs = (svg: string) =>
  svg
    .replace(/\bdata-hero-part="robbie"/g, 'data-hero-part="robbie" opacity="0"')
    .replace(/\bdata-hero-part="mclaughlin"/g, 'data-hero-part="mclaughlin" opacity="0"');

